  window.toggleCalendarSource=function(){const el=document.getElementById('calendarSourceDetail');if(!el)return;el.hidden=!el.hidden};
  const setupModal=(title,eyebrow,muted,body,saveText,saveHandler)=>{const modal=document.getElementById('modal'),bg=document.getElementById('modalBg'),stream=document.getElementById('stream'),bottom=document.querySelector('.modal-bottom');if(!modal||!bg||!stream||!bottom)return;modal.classList.remove('create-open','course-processing','closing');bg.classList.remove('create-open','closing');document.body.classList.add('modal-lock');document.documentElement.classList.add('modal-lock');document.getElementById('modalTitle').textContent=title;const mark=modal.querySelector('.modal-header .eyebrow');if(mark)mark.textContent=eyebrow;const mutedEl=modal.querySelector(':scope > .muted');if(mutedEl)mutedEl.textContent=muted||'';stream.innerHTML=body;bottom.style.display='flex';bottom.innerHTML='<button id="calendarModalCancel" class="btn secondary" type="button">取消</button><button id="calendarModalSave" class="btn primary" type="button">'+esc(saveText||'保存')+'</button>';modal.classList.add('open','calendar-edit-open');bg.classList.add('open');document.getElementById('calendarModalCancel').onclick=()=>window.closeAI();document.getElementById('calendarModalSave').onclick=saveHandler;setTimeout(()=>{const first=stream.querySelector('textarea,input,button');if(first)first.focus()},30)};
  window.openCalendarEdit=function(index){const state=stateForCourse(),row=state.rows&&state.rows[index];if(!row)return;const m=courseMeta(),isDiscrete=m.id==='discrete';const body='<form id="calendarEditForm" class="calendar-edit-form"><div class="calendar-edit-meta"><div><span>周次</span><b>'+esc(row.week)+'</b></div><div><span>课程编号</span><b>'+esc(m.code)+'</b></div><div><span>版本</span><b>'+esc(state.version||'v3')+'</b></div></div><label>讲授内容<textarea name="lecture">'+esc(row.lecture||'')+'</textarea></label><label>实验或实践内容<textarea name="practice">'+esc(row.practice||'')+'</textarea></label><label>课外作业<textarea name="homework">'+esc(row.homework||'')+'</textarea></label><div class="calendar-edit-hours"><label>讲授学时<input name="lectureHours" type="number" min="0" max="40" value="'+Number(row.lectureHours||0)+'"></label><label>实验学时<input name="experimentHours" type="number" min="0" max="40" value="'+Number(row.experimentHours||0)+'"></label><label>实践学时<input name="practiceHours" type="number" min="0" max="40" value="'+Number(row.practiceHours||0)+'"></label></div><label>授课教师<input name="teacher" value="'+esc(row.teacher||m.teacher)+'"></label><p class="calendar-edit-hint">'+(isDiscrete?'学校模板原文会保留在来源记录中；':'当前课程尚未导入学校模板；')+'修改本周计划后，当前日历标记为“编辑中”，提交审核前会重新执行学时和覆盖校验。</p></form>';setupModal('编辑 '+row.week,'教学日历 · 周计划编辑',isDiscrete?'结构化字段 · 来源：学校教学日历 Word 模板':'结构化字段 · 当前课程',body,'保存本周计划',()=>{const form=document.getElementById('calendarEditForm');if(!form)return;const next=Object.assign({},row,{lecture:form.elements.lecture.value.trim()||'—',practice:form.elements.practice.value.trim()||'—',homework:form.elements.homework.value.trim()||'—',lectureHours:Math.max(0,Number(form.elements.lectureHours.value)||0),experimentHours:Math.max(0,Number(form.elements.experimentHours.value)||0),practiceHours:Math.max(0,Number(form.elements.practiceHours.value)||0),teacher:form.elements.teacher.value.trim()||m.teacher,status:'edited',course_id:m.id,course_version_id:m.id+'-'+(state.version||'v3')});state.rows[index]=next;state.status='editing';state.updatedAt=new Date().toISOString();saveCurrentState(state);window.closeAI();if(window.showSyllabusToast)window.showSyllabusToast(row.week+'计划已保存，状态变为编辑中');setTimeout(()=>window.render(),220)});};
  window.checkCalendar=function(){const m=courseMeta(),state=stateForCourse(),rows=state.rows||[],total=rows.reduce((sum,r)=>sum+Number(r.lectureHours||0)+Number(r.experimentHours||0)+Number(r.practiceHours||0),0),missing=rows.filter(r=>!String(r.lecture||'').trim()||String(r.lecture).trim()==='—'||String(r.lecture).includes('尚未建立')).length,syllabusHours=m.syllabusHours||m.hours,mismatch=total!==syllabusHours;const body='<div class="calendar-check-list"><div class="calendar-check-item '+(mismatch?'fail':'pass')+'"><span>总学时与正式大纲（'+syllabusHours+' 学时）一致</span><b>'+(mismatch?'未通过':'通过')+'</b></div><div class="calendar-check-item '+(m.id==='discrete'?'pass':'fail')+'"><span>'+(m.id==='discrete'?'学校模板原文（'+m.hours+' 学时）已保留':'学校教学日历模板已导入')+'</span><b>'+(m.id==='discrete'?'已记录':'待上传')+'</b></div><div class="calendar-check-item '+(missing?'fail':'pass')+'"><span>16 周计划均已建立</span><b>'+(missing?'有 '+missing+' 周待补充':'通过')+'</b></div><div class="calendar-check-item '+(missing?'fail':'pass')+'"><span>正式授课内容覆盖全部周次</span><b>'+(missing?'有 '+missing+' 周待补充':'通过')+'</b></div><div class="calendar-check-item pass"><span>实验 / 实践内容按栏目填写</span><b>通过</b></div></div>'+(mismatch||missing?'<p class="calendar-edit-hint" style="margin-top:12px">发生了什么：日历与正式大纲存在需要处理的校验项。影响：当前版本不能提交审核。下一步：编辑周计划或先在教学大纲中对齐总学时后再次检查；修正后可重试。</p>':'<p class="calendar-edit-hint" style="margin-top:12px;background:#eefaf7;color:#167c73">检查完成：当前版本满足提交条件。仍建议教师确认学校校历和节假日后再提交审核。</p>');setupModal('日历检查结果','教学日历 · 提交前检查','总学时、章节覆盖和栏目完整性',body,'关闭',()=>window.closeAI());document.getElementById('calendarModalCancel').style.display='none'};
  window.openCalendarAI=function(){const m=courseMeta(),isDiscrete=m.id==='discrete',benchmark=m.syllabusHours||m.hours;const suggestion=isDiscrete?'• 第 14 周：Dijkstra、Kruskal 算法练习，作为图论算法复习节点。<br>• 第 15 周：Prim 与旅行商问题练习，建议加入小组讨论。<br>• 第 16 周：答疑辅导，收集共性问题并回顾课程目标。':'当前课程尚未导入学校模板。建议先补充校历与周学时，再生成教学安排。';setupModal('AI 教学安排建议','AI 助手 · MOCK 模式','只提供顺序、复习、测验、答疑和作业节点建议，不修改正式学时与校历','<div class="calendar-ai-box"><div class="process-lead"><span class="process-dot live"></span><div><strong>正在分析教学大纲与课程校历…</strong><small>已脱敏处理课程结构 · 排队状态：执行中</small></div></div><div class="process-live"><span class="process-live-label">思考中</span>对照 '+benchmark+' 学时基准，检查章节顺序与复习节点…</div><div id="calendarAiResult" class="calendar-ai-result" hidden></div></div>','保存建议',()=>{try{localStorage.setItem('ai-jiaowu-calendar-ai-result-'+m.id,JSON.stringify({savedAt:new Date().toISOString(),status:'draft',content:suggestion.replace(/<br>/g,' ')}))}catch{}window.closeAI();if(window.showSyllabusToast)window.showSyllabusToast('AI 排课建议已保存为草稿，不会改写正式日历')});setTimeout(()=>{const result=document.getElementById('calendarAiResult');if(result){result.hidden=false;result.innerHTML='<strong>已生成安排建议</strong><p>'+suggestion+'</p><span class="tag ok">建议结果 · 待教师确认</span>'}},900)};
  window.submitCalendarReview=function(){const state=stateForCourse(),m=courseMeta(),total=(state.rows||[]).reduce((sum,r)=>sum+Number(r.lectureHours||0)+Number(r.experimentHours||0)+Number(r.practiceHours||0),0),syllabusHours=m.syllabusHours||m.hours;if(total!==syllabusHours){if(window.showSyllabusToast)window.showSyllabusToast('提交被阻止：日历 '+total+' 学时与正式大纲 '+syllabusHours+' 学时不一致，请先对齐');return}state.status='pending_review';state.updatedAt=new Date().toISOString();saveCurrentState(state);if(window.showSyllabusToast)window.showSyllabusToast('教学日历已提交教学秘书审核');setTimeout(()=>window.render(),220)};
